import React, { useState, useEffect, useRef } from 'react';
import axios from 'axios';
import './App.css';  // Assuming App.css is imported here if needed, but per your code it's in index.css

function App() {
  const [user, setUser] = useState(null);
  const [page, setPage] = useState('login');
  const [emailInput, setEmailInput] = useState('');
  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(false);
  const [showForm, setShowForm] = useState(false);
  const [editingItem, setEditingItem] = useState(null);
  const [formData, setFormData] = useState({});
  const [courses, setCourses] = useState([]);
  const [enrolledCourseIds, setEnrolledCourseIds] = useState([]);
  const [selectedAssignment, setSelectedAssignment] = useState(null);
  const [submissionText, setSubmissionText] = useState('');
  const [showFileModal, setShowFileModal] = useState(false);
  const [currentSubmissionText, setCurrentSubmissionText] = useState('');
  const [currentSubmissionId, setCurrentSubmissionId] = useState(null);
  const [showGradeModal, setShowGradeModal] = useState(false);
  const [submissionToGrade, setSubmissionToGrade] = useState(null);
  const [gradeValue, setGradeValue] = useState('');
  const [feedbackText, setFeedbackText] = useState('');
  const [showConfirmDelete, setShowConfirmDelete] = useState(false);
  const [itemToDelete, setItemToDelete] = useState(null);
  const [deleteBase, setDeleteBase] = useState('');
  const [allUsers, setAllUsers] = useState([]);
  // AI Chat
  const [showChat, setShowChat] = useState(false);
  const [chatMessages, setChatMessages] = useState([
    { sender: 'bot', text: "Hello! I'm your Student Portal assistant. Ask me anything about how to use the portal!" }
  ]);
  const [chatInput, setChatInput] = useState('');
  const [chatLoading, setChatLoading] = useState(false);
  const chatEndRef = useRef(null);

  const API = 'http://localhost:5000/api';

  const getEndpoint = (pageName) => {
    if (pageName === 'courses') return 'courses';
    if (pageName === 'assignments') return 'assignments';
    if (pageName === 'announcements') return 'announcements';
    if (pageName === 'submissions') {
      return user?.role === 'student' ? `submissions?studentid=${user.id}` : 'submissions';
    }
    if (pageName === 'students') return 'users?role=student';
    if (pageName === 'instructors') return 'users?role=instructor';
    return null;
  };

  const getEmptyForm = (pageName) => {
    if (pageName === 'courses') return { title: '', description: '', syllabus: '' };
    if (pageName === 'assignments') return { title: '', duedate: '', description: '', courseid: '' };
    if (pageName === 'announcements') return { title: '', message: '', courseid: '' };
    if (pageName === 'students') return { name: '', email: '' };
    if (pageName === 'instructors') return { name: '', email: '', courseTitle: '', courseDescription: '', courseSyllabus: '' };
    return {};
  };

  const login = async (e) => {
    e.preventDefault();
    if (!emailInput.trim()) return alert('Please enter your email');
    try {
      const res = await axios.post(`${API}/users/login`, { email: emailInput.trim() });
      setUser(res.data);
      setPage(res.data.role === 'admin' ? 'instructors' : 'courses');
    } catch (err) {
      alert('Login failed — user not found');
    }
  };

  const fetchData = async () => {
    if (!user || !page) return;
    setLoading(true);
    let endpoint = getEndpoint(page);
    if (!endpoint) return;
    let url = `${API}/${endpoint}`;
    if (page === 'courses' && user.role === 'instructor') {
      url += `?instructorid=${user.id}`;
    }
    if (['assignments', 'announcements', 'submissions'].includes(page) && selectedAssignment) {
      url += `?assignmentid=${selectedAssignment.id}`;
    }
    try {
      const res = await axios.get(url);
      setData(res.data);
    } catch (err) {
      alert('Error fetching data');
    }
    setLoading(false);
  };

  const fetchCourses = async () => {
    let url = `${API}/courses`;
    if (user.role === 'instructor') url += `?instructorid=${user.id}`;
    try {
      const res = await axios.get(url);
      setCourses(res.data);
      if (user.role === 'student') {
        setEnrolledCourseIds(res.data.filter(c => c.students.includes(user.id)).map(c => c.id));
      }
    } catch (err) {
      alert('Error fetching courses');
    }
  };

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    try {
      if (!editingItem) {
        if (page === 'instructors') {
          const instructorData = { name: formData.name, email: formData.email, role: 'instructor' };
          const resInstructor = await axios.post(`${API}/users`, instructorData);
          const newInstructor = resInstructor.data;
          const courseData = {
            title: formData.courseTitle,
            description: formData.courseDescription,
            syllabus: formData.courseSyllabus,
            instructorid: newInstructor.id
          };
          await axios.post(`${API}/courses`, courseData);
        } else {
          let postData = formData;
          if (page === 'courses' && user.role === 'instructor') postData.instructorid = user.id;
          if (['assignments', 'announcements'].includes(page)) postData.courseid = formData.courseid;
          if (page === 'students') postData.role = 'student';
          await axios.post(`${API}/${getEndpoint(page)}`, postData);
        }
      } else {
        await axios.put(`${API}/${getEndpoint(page)}/${editingItem.id}`, formData);
      }
      fetchData();
      setShowForm(false);
      setEditingItem(null);
      setFormData(getEmptyForm(page));
    } catch (err) {
      alert('Error submitting form');
    }
    setLoading(false);
  };

  const handleEdit = (item) => {
    setEditingItem(item);
    setFormData(item);
    setShowForm(true);
  };

  const prepareDelete = (item) => {
    setItemToDelete(item);
    setDeleteBase(getEndpoint(page));
    setShowConfirmDelete(true);
  };

  const confirmDelete = async () => {
    try {
      await axios.delete(`${API}/${deleteBase}/${itemToDelete.id}`);
      fetchData();
    } catch (err) {
      alert('Error deleting');
    }
    setShowConfirmDelete(false);
  };

  const handleEnroll = async (courseId) => {
    try {
      await axios.post(`${API}/courses/${courseId}/enroll`, { studentid: user.id });
      fetchCourses();
      fetchData();
    } catch (err) {
      alert('Error enrolling');
    }
  };

  const handleDrop = async (courseId) => {
    try {
      await axios.post(`${API}/courses/${courseId}/drop`, { studentid: user.id });
      fetchCourses();
      fetchData();
    } catch (err) {
      alert('Error dropping');
    }
  };

  const openSubmissionModal = (assignment) => {
    setSelectedAssignment(assignment);
    setSubmissionText('');
    setShowFileModal(true);
  };

  const submitSubmission = async () => {
    try {
      await axios.post(`${API}/submissions`, { assignmentid: selectedAssignment.id, studentid: user.id, fileurl: submissionText });
      setShowFileModal(false);
      fetchData();
    } catch (err) {
      alert('Error submitting');
    }
  };

  const openGradeModal = (submission) => {
    setSubmissionToGrade(submission);
    setGradeValue(submission.grade || '');
    setFeedbackText(submission.feedback || '');
    setShowGradeModal(true);
  };

  const submitGrade = async () => {
    try {
      await axios.put(`${API}/submissions/${submissionToGrade.id}/grade`, { grade: gradeValue, feedback: feedbackText });
      setShowGradeModal(false);
      fetchData();
    } catch (err) {
      alert('Error grading');
    }
  };

  const sendChatMessage = async () => {
    if (!chatInput.trim()) return;
    setChatMessages([...chatMessages, { sender: 'user', text: chatInput }]);
    setChatInput('');
    setChatLoading(true);
    try {
      const res = await axios.post(`${API}/chat`, { message: chatInput });
      setChatMessages(prev => [...prev, { sender: 'bot', text: res.data.reply }]);
    } catch (err) {
      setChatMessages(prev => [...prev, { sender: 'bot', text: 'AI is temporarily unavailable.' }]);
    }
    setChatLoading(false);
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    if (user && page !== 'login') {
      fetchData();
      if (page === 'courses') fetchCourses();
    }
  }, [page, user, selectedAssignment]);

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [chatMessages]);

  const getTableColumns = (pageName) => {
    switch (pageName) {
      case 'courses': return [{label: 'Title', key: 'title'}, {label: 'Description', key: 'description'}, {label: 'Syllabus', key: 'syllabus'}];
      case 'assignments': return [{label: 'Title', key: 'title'}, {label: 'Due Date', key: 'duedate'}, {label: 'Description', key: 'description'}];
      case 'announcements': return [{label: 'Title', key: 'title'}, {label: 'Message', key: 'message'}];
      case 'submissions': return [{label: 'File URL', key: 'fileurl'}, {label: 'Grade', key: 'grade'}, {label: 'Feedback', key: 'feedback'}];
      case 'students':
      case 'instructors': return [{label: 'Name', key: 'name'}, {label: 'Email', key: 'email'}];
      default: return [];
    }
  };

  return (
    <div>
      {!user ? (
        <div className="container">
          <h1>Login to NM Student Portal</h1>
          <form onSubmit={login}>
            <input
              type="email"
              value={emailInput}
              onChange={(e) => setEmailInput(e.target.value)}
              placeholder="Enter your email"
              required
              style={{ padding: '10px', margin: '10px 0', width: '100%' }}
            />
            <button type="submit" className="btn">Login</button>
          </form>
        </div>
      ) : (
        <>
          <nav>
            {user.role === 'student' && (
              <>
                <a onClick={() => setPage('courses')}>Courses</a>
                <a onClick={() => setPage('assignments')}>Assignments</a>
                <a onClick={() => setPage('announcements')}>Announcements</a>
                <a onClick={() => setPage('submissions')}>Submissions</a>
              </>
            )}
            {user.role === 'instructor' && (
              <>
                <a onClick={() => setPage('courses')}>Courses</a>
                <a onClick={() => setPage('assignments')}>Assignments</a>
                <a onClick={() => setPage('announcements')}>Announcements</a>
                <a onClick={() => setPage('submissions')}>Submissions</a>
              </>
            )}
            {user.role === 'admin' && (
              <>
                <a onClick={() => setPage('instructors')}>Instructors</a>
                <a onClick={() => setPage('students')}>Students</a>
              </>
            )}
            <a onClick={() => setShowChat(true)}>AI Help</a>
            <a onClick={() => { setUser(null); setPage('login'); }}>Logout</a>
          </nav>
          <div className="container">
            <h2>{page.toUpperCase()}</h2>
            {!showForm && <button className="btn" onClick={() => { setShowForm(true); setEditingItem(null); setFormData(getEmptyForm(page)); }}>Add New</button>}
            {loading ? <p>Loading...</p> : (
              <table>
                <thead>
                  <tr>
                    {getTableColumns(page).map(col => <th key={col.label}>{col.label}</th>)}
                    <th>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {data.map(item => (
                    <tr key={item.id}>
                      {getTableColumns(page).map(col => <td key={col.key}>{item[col.key]}</td>)}
                      <td>
                        <button className="btn" onClick={() => handleEdit(item)}>Edit</button>
                        <button className="btn" onClick={() => prepareDelete(item)}>Delete</button>
                        {page === 'courses' && user.role === 'student' && (
                          enrolledCourseIds.includes(item.id) ? (
                            <button className="btn" onClick={() => handleDrop(item.id)}>Drop</button>
                          ) : (
                            <button className="btn" onClick={() => handleEnroll(item.id)}>Enroll</button>
                          )
                        )}
                        {page === 'assignments' && user.role === 'student' && <button className="btn" onClick={() => openSubmissionModal(item)}>Submit</button>}
                        {page === 'submissions' && user.role === 'instructor' && <button className="btn" onClick={() => openGradeModal(item)}>Grade</button>}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            )}
            {showForm && (
              <form onSubmit={handleSubmit}>
                {Object.keys(formData).map(key => (
                  <input key={key} type="text" name={key} value={formData[key]} onChange={handleChange} placeholder={key.charAt(0).toUpperCase() + key.slice(1)} required style={{ display: 'block', margin: '10px 0' }} />
                ))}
                <button className="btn" type="submit">{editingItem ? 'Update' : 'Create'}</button>
                <button className="btn" type="button" onClick={() => setShowForm(false)}>Cancel</button>
              </form>
            )}
          </div>
          {showFileModal && (
            <div style={{ position: 'fixed', top: '20%', left: '30%', width: '40%', background: 'white', padding: '20px', borderRadius: '10px', boxShadow: '0 0 10px rgba(0,0,0,0.5)' }}>
              <h3>Submit for {selectedAssignment?.title}</h3>
              <input type="text" value={submissionText} onChange={(e) => setSubmissionText(e.target.value)} placeholder="File URL or Text" style={{ width: '100%', margin: '10px 0' }} />
              <button className="btn" onClick={submitSubmission}>Submit</button>
              <button className="btn" onClick={() => setShowFileModal(false)}>Cancel</button>
            </div>
          )}
          {showGradeModal && (
            <div style={{ position: 'fixed', top: '20%', left: '30%', width: '40%', background: 'white', padding: '20px', borderRadius: '10px', boxShadow: '0 0 10px rgba(0,0,0,0.5)' }}>
              <h3>Grade Submission</h3>
              <input type="number" value={gradeValue} onChange={(e) => setGradeValue(e.target.value)} placeholder="Grade" style={{ width: '100%', margin: '10px 0' }} />
              <textarea value={feedbackText} onChange={(e) => setFeedbackText(e.target.value)} placeholder="Feedback" style={{ width: '100%', margin: '10px 0' }} />
              <button className="btn" onClick={submitGrade}>Save</button>
              <button className="btn" onClick={() => setShowGradeModal(false)}>Cancel</button>
            </div>
          )}
          {showConfirmDelete && (
            <div style={{ position: 'fixed', top: '20%', left: '30%', width: '40%', background: 'white', padding: '20px', borderRadius: '10px', boxShadow: '0 0 10px rgba(0,0,0,0.5)' }}>
              <p>Confirm delete?</p>
              <button className="btn" onClick={confirmDelete}>Yes</button>
              <button className="btn" onClick={() => setShowConfirmDelete(false)}>No</button>
            </div>
          )}
          {showChat && (
            <div style={{
              position: 'fixed',
              top: '10%',
              right: '10%',
              width: '400px',
              height: '600px',
              background: 'white',
              borderRadius: '16px',
              boxShadow: '0 20px 50px rgba(0,0,0,0.3)',
              display: 'flex',
              flexDirection: 'column',
              zIndex: 1000
            }}>
              <div style={{ padding: '16px', background: '#667eea', color: 'white', borderRadius: '16px 16px 0 0', fontWeight: '600', fontSize: '1.1rem', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                NM Portal Assistant
                <button onClick={() => setShowChat(false)} style={{ background: 'none', border: 'none', color: 'white', fontSize: '24px', cursor: 'pointer' }}>×</button>
              </div>
              <div style={{ flex: 1, padding: '16px', overflowY: 'auto', background: '#f8fafc' }}>
                {chatMessages.map((msg, i) => (
                  <div key={i} style={{ margin: '10px 0', textAlign: msg.sender === 'user' ? 'right' : 'left' }}>
                    <div style={{
                      display: 'inline-block',
                      maxWidth: '80%',
                      padding: '12px 16px',
                      borderRadius: '16px',
                      background: msg.sender === 'user' ? '#667eea' : '#e2e8f0',
                      color: msg.sender === 'user' ? 'white' : '#333'
                    }}>
                      {msg.text}
                    </div>
                  </div>
                ))}
                {chatLoading && <div style={{ textAlign: 'left' }}><div style={{ display: 'inline-block', padding: '12px 16px', background: '#e2e8f0', borderRadius: '16px' }}>Thinking...</div></div>}
                <div ref={chatEndRef} />
              </div>
              <div style={{ padding: '16px', borderTop: '1px solid #e2e8f0', display: 'flex' }}>
                <input
                  type="text"
                  value={chatInput}
                  onChange={(e) => setChatInput(e.target.value)}
                  onKeyPress={(e) => e.key === 'Enter' && sendChatMessage()}
                  placeholder="Ask about the portal..."
                  style={{ flex: 1, padding: '12px', borderRadius: '8px', border: '2px solid #e2e8f0', fontSize: '1rem' }}
                />
                <button
                  onClick={sendChatMessage}
                  disabled={chatLoading}
                  style={{ marginLeft: '10px', padding: '12px 20px', background: '#667eea', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer' }}
                >
                  Send
                </button>
              </div>
            </div>
          )}
        </>
      )}
      <footer>
        <h3>Student Portal © 2025</h3>
        <p>Nikko Manuel - Marlon Chipa Learning Management System</p>
      </footer>
    </div>
  );
}

export default App;
